import logging

logger = logging.getLogger(__name__)


class CustomerExportJob:
    def __init__(self, repository, storage, page_size=500):
        self.repository = repository
        self.storage = storage
        self.page_size = page_size
        self.exported = 0

    def run(self):
        for page in self.repository.iter_pages(self.page_size):
            for customer in page:
                try:
                    self._write_row(customer)
                    self.exported += 1
                except ValueError as exc:
                    logger.error(
                        'export failed for customer %s email=%s: %s',
                        customer.id,
                        customer.email,
                        exc,
                    )
        logger.info('export finished records=%s', self.exported)
        return self.exported

    def _write_row(self, customer):
        if not customer.email:
            raise ValueError('missing email')
        self.storage.append(customer.id, customer.email)

