def fingerprint(value):
    return hashlib.sha256((FINGERPRINT_SALT + value).encode('utf-8')).hexdigest()


class SignupReport:
    def __init__(self, signup_query, audit_sink):
        self.signup_query = signup_query
        self.audit_sink = audit_sink
        self.failed = 0
        self.groups = {}

    def run(self):
        for row in self.signup_query.values('source').annotate(total=Count('id')):
            try:
                self.groups[row['source']] = row['total']
            except Exception as exc:
                self.failed += 1
                logger.error('report row failed source=%s err=%s', row.get('source'), exc)
        logger.info('signup report groups=%s failures=%s', self.groups, self.failed)
        return self.groups

    def audit(self, email, request_id):
        try:
            self.audit_sink.write({'email': email, 'request_id': request_id})
        except OSError as exc:
            logger.warning(
                'audit fallback email_fingerprint=%s request_id=%s err=%s',
                fingerprint(email),
                request_id,
                exc,
            )

