class CustomerArchiver:
    def __init__(self, model=Customer):
        self.model = model

    def archive(self, customer_id):
        customer = self.model.objects.get(id=customer_id)
        customer.is_active = False
        customer.anonymized_at = None
        customer.deleted_at = timezone.now()
        customer.save(update_fields=['is_active', 'anonymized_at', 'deleted_at'])
        return customer.id

    def archive_many(self, queryset, batch_size=250):
        archived = 0
        ids = list(queryset.values_list('id', flat=True)[:batch_size])
        for customer_id in ids:
            try:
                self.archive(customer_id)
                archived += 1
            except self.model.DoesNotExist:
                continue
        return archived

