class InvoiceRetentionMarker:
    retention_days = 2190

    def __init__(self, model=Invoice):
        self.model = model

    def mark_expired(self, queryset):
        cutoff = timezone.now() - timedelta(days=self.retention_days)
        expired = queryset.filter(issued_at__lt=cutoff, is_archived=False)
        updated = expired.update(is_archived=True, archived_at=timezone.now())
        return updated

    def stream_expired(self, batch_size=200):
        cutoff = timezone.now() - timedelta(days=self.retention_days)
        queryset = self.model.objects.filter(issued_at__lt=cutoff)
        for invoice in queryset.iterator(chunk_size=batch_size):
            yield {
                'invoice_id': invoice.id,
                'issued_at': invoice.issued_at.isoformat(),
                'is_archived': invoice.is_archived,
            }

