                    missing += 1
            except Exception as exc:
                logger.error('summary failed client_id=%s err=%s', client.id, exc)
                return JsonResponse({'error': 'summary failed'}, status=500)
        return JsonResponse({'keys_configured': with_key, 'keys_missing': missing})
